    java.util.Map<String, java.util.Set<String>> uses = uses(tree(person.getSheetId()));
    if (usedByOther(uses, name, person)) {
        return true;
    }
    for (String alias : person.getAliases()) {
        if (usedByOther(uses, alias, person)) {
            return true;
        }
    }
