import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';

export type SheetToday = { sheet: string; today: string; archived: boolean };

export const sheetTodayKey = (sheet: string, asOf = '') => ['sheet', sheet, 'today', asOf] as const;

/** The sheet's today (YYYY-MM-DD; the as-of date while one is set). Every date decision and default date on screen reads this —
 *  never `new Date()`. Undefined while loading. */
export function useSheetToday(sheet: string): string | undefined {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: sheetTodayKey(sheet, asOf),
    queryFn: () => getJson<SheetToday>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/today`, asOf)),
    enabled: sheet !== '',
  });
  return data?.today;
}

/** Whether the sheet is archived (everything visible, every change refused). Undefined while loading. */
export function useSheetArchived(sheet: string): boolean | undefined {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: sheetTodayKey(sheet, asOf),
    queryFn: () => getJson<SheetToday>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/today`, asOf)),
    enabled: sheet !== '',
  });
  return data?.archived;
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` lets a form tell a conflict (409) from a refusal. */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** The status a change is refused with while the screen is shown as of a date. */
export const AS_OF_REFUSED = 423;

/** Whether the screen is shown as of a date (the `asof` search param, see features/asof): every change is refused. */
function viewingAsOf(): boolean {
  return new URLSearchParams(window.location.search).get('asof') ? true : false;
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  // An as-of view shows the sheet as it stood: a change asked for from it is refused, as any refused change, and
  // nothing reaches the store.
  if ((init?.method ?? 'GET') !== 'GET' && viewingAsOf()) {
    throw new HttpError(`${init?.method} ${path} -> refused: the screen is shown as of a date`, AS_OF_REFUSED);
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
